'use strict';
const $=id=>document.getElementById(id),canvas=$('field'),ctx=canvas.getContext('2d'),{roster,specs,Match}=PokeSim;
const images={};function preload(teams){teams.flat().forEach(p=>{if(images[p.id])return;images[p.id]=new Image();images[p.id].src=`assets/${p.id}.png`})}preload([roster]);
let squads=[roster,roster],scoutingTeam=0,coaching=true,waiting=false,selectedPlay='quick',previewEvent=null;
const stadium=new PokeStadium.Stadium(canvas,images);
let match=new Match(),running=false,paused=false,speed=1,phase=0,event=null,players=[],side='offense',box='offense',last=0,sound=true,feed=[],elapsed=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let motion=null,particles=[],camera=35,shake=0,replaying=false,replayed=false,frameState=null,fxClock=0,ambientTime=0,fullEffects=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const effectsButton=$('effects');function effectsLabel(){effectsButton.textContent='ANIMATIONS · '+(fullEffects?'FULL':'REDUCED');effectsButton.setAttribute('aria-pressed',String(fullEffects))}effectsButton.onclick=()=>{fullEffects=!fullEffects;particles=[];effectsLabel()};effectsLabel();
const music=new PokeMusic.ChipMusic(),fieldFX=new PokeFX.FieldFX();fieldFX.preload();
function loadAudioPref(key){try{return localStorage.getItem('poke-bowl-'+key)}catch{return null}}
function saveAudioPref(key,value){try{localStorage.setItem('poke-bowl-'+key,String(value))}catch{}}
sound=loadAudioPref('fx')!=='off';fieldFX.setEnabled(sound);
function fxUI(){$('sound').textContent=sound?'FX ON':'FX OFF';$('sound').setAttribute('aria-pressed',String(sound))}fxUI();
function enableFX(){if(sound)fieldFX.prepare().catch(error=>console.warn('Field effects could not start:',error))}
let musicTouched=loadAudioPref('music')!==null,musicWanted=loadAudioPref('music')==='on';
const savedVolume=loadAudioPref('volume');if(savedVolume!==null&&Number.isFinite(+savedVolume))music.setVolume(clamp(+savedVolume/100,0,1));
const savedTrack=loadAudioPref('track');if(PokeMusic.tracks[savedTrack])music.setTrack(savedTrack);
$('track').value=music.track;$('musicVolume').value=Math.round(music.volume*100);$('volumeValue').textContent=Math.round(music.volume*100)+'%';
function musicUI(){let playing=music.enabled;$('music').textContent=playing?'♫ MUSIC ON':'♫ MUSIC OFF';$('music').setAttribute('aria-pressed',String(playing));$('nowPlaying').textContent=playing?'NOW PLAYING · '+PokeMusic.tracks[music.track].name:musicTouched?'Original 120 BPM stadium mixes · tap MUSIC to listen':'Original 120 BPM stadium mixes · starts at kickoff'}
music.onChange=musicUI;musicUI();
async function enableMusic(auto=false){if(auto&&!musicTouched)musicWanted=true;if(!musicWanted)return;try{await music.play();saveAudioPref('music','on')}catch(error){console.warn('Stadium music could not start:',error);music.stop();$('nowPlaying').textContent='Tap MUSIC to enable audio in this browser.'}}
$('music').onclick=()=>{musicTouched=true;musicWanted=!music.enabled;saveAudioPref('music',musicWanted?'on':'off');if(musicWanted)enableMusic();else music.stop();musicUI()};
$('track').onchange=()=>{music.setTrack($('track').value);saveAudioPref('track',music.track);musicTouched=true;musicWanted=true;saveAudioPref('music','on');enableMusic()};
$('musicVolume').oninput=()=>{let value=+$('musicVolume').value;music.setVolume(value/100);$('volumeValue').textContent=value+'%';saveAudioPref('volume',value)};
document.addEventListener('visibilitychange',()=>{if(document.hidden){music.stop();fieldFX.stop()}else{if(musicWanted)enableMusic();enableFX()}});
const skill=(name,value)=>`<div class="skill"><span>${name}</span><span class="meter"><i style="width:${value}%"></i></span><b>${value}</b></div>`;
function playerHeader(p){return `<div class="card-top"><img src="assets/${p.id}.png" alt=""><div><h3>${p.name}</h3><small>${p.pos} · ${p.side.toUpperCase()}</small></div><div class="ovr">${p.ovr}<small>OVR</small></div></div>`}
function renderRatings(){ $('ratings').innerHTML=squads[scoutingTeam].filter(p=>p.side===side).map(p=>`<button class="player-card" data-player="${p.id}" aria-label="View ${p.name} ${p.pos} scouting report">${playerHeader(p)}${specs[p.pos].map(k=>skill(k,p.ratings[k])).join('')}</button>`).join('');document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{let p=squads[scoutingTeam].find(p=>p.id===+b.dataset.player);$('playerReport').innerHTML=playerHeader(p)+`<p>${p.note}</p>`+Object.entries(p.ratings).map(([k,v])=>skill(k,v)).join('');$('playerDialog').showModal()})}
const columns={offense:[['att','ATT'],['cmp','CMP'],['passYds','PASS YD'],['passTD','PASS TD'],['ints','INT'],['rush','CAR'],['rushYds','RUSH YD'],['rushTD','RUSH TD'],['targets','TGT'],['rec','REC'],['recYds','REC YD'],['recTD','REC TD']],defense:[['snaps','SNAPS'],['tackles','TKL'],['sacks','SACK'],['picks','INT'],['pressures','PRESS'],['blocks','KEY BLK']]};
function renderBox(){let t=+$('statTeam').value||0,cols=columns[box];$('statHead').innerHTML='<tr><th>PLAYER</th><th>POS</th>'+cols.map(([,s])=>`<th>${s}</th>`).join('')+'</tr>';$('statBody').innerHTML=squads[t].filter(p=>box==='offense'?p.side==='offense':true).map(p=>`<tr><td>${p.name}</td><td>${p.pos}</td>${cols.map(([k])=>`<td>${match.stats[t][p.id][k]}</td>`).join('')}</tr>`).join('')}
function label(e){return e.touchdown?'TOUCHDOWN':e.interception?'INTERCEPTION':e.fumble?'FUMBLE':e.safety?'SAFETY':e.type==='kick'?'FIELD GOAL':e.type==='punt'?'PUNT':e.firstDown?'FIRST DOWN':e.type==='sack'?'SACK':e.type==='run'?'RUSH':e.complete?'COMPLETE':'INCOMPLETE'}
function hud(before=false){let m=before&&event?event:match;$('you').textContent=String(before&&event?event.scoreBefore[0]:match.score[0]).padStart(2,'0');$('cpu').textContent=String(before&&event?event.scoreBefore[1]:match.score[1]).padStart(2,'0');$('quarter').textContent='Q'+m.quarter;$('time').textContent=`${Math.floor(m.clock/60)}:${String(m.clock%60).padStart(2,'0')}`;let b=before&&event?event.start:match.ball,f=before&&event?event.first:match.first;$('down').textContent=match.over&&!before?'FINAL':`${['1ST','2ND','3RD','4TH'][m.down-1]} & ${f===100?'GOAL':Math.ceil(f-b)} · ${b<50?'OWN '+b:'OPP '+(100-b)}`;$('possession').textContent=(event?.team??match.team)===0?'BLUE POSSESSION →':'RED POSSESSION ←'}
function playDiagram(key){const routes=PokeMotion.routes(key,20,squads[0]),line=112;return `<svg viewBox="0 0 112 56" aria-hidden="true"><path d="M28 4V52" stroke="#83b3bc" stroke-width="1" stroke-dasharray="3 3"/><path d="M4 4H108M4 52H108" stroke="#49694f"/>${routes.map(r=>{const points=r.points.map(p=>[28+(p.y-20)*2,(p.x-54)/532*44+6]);const end=points.at(-1),prev=points.at(-2),angle=Math.atan2(end[1]-prev[1],end[0]-prev[0]);return `<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${r.primary?'#f0d979':'#9db8a0'}" stroke-width="${r.primary?1.8:1.2}"/><path d="M${end[0]-5*Math.cos(angle-.5)} ${end[1]-5*Math.sin(angle-.5)}L${end.join(' ')}L${end[0]-5*Math.cos(angle+.5)} ${end[1]-5*Math.sin(angle+.5)}" fill="none" stroke="#f0d979"/>`}).join('')}${[8,18,23,28,33,38,48].map(y=>`<circle cx="25" cy="${y}" r="2.3" fill="#d0e3ce"/>`).join('')}<circle cx="18" cy="28" r="2.5" fill="#79c7e4"/></svg>`}
function renderPlayCards(){ $('playCards').innerHTML=Object.entries(PokeSim.calls).map(([key,call])=>`<button class="play-card ${key===selectedPlay?'active':''}" data-call="${key}" aria-pressed="${key===selectedPlay}" style="--play-color:${call.color}"><strong><i></i>${call.name}</strong>${playDiagram(key)}<small>${call.description}</small></button>`).join('');$('playCards').querySelectorAll('[data-call]').forEach(button=>button.onclick=()=>{if(!waiting||paused||!coaching)return;selectedPlay=button.dataset.call;formation();renderPlayCards();coachUI()}); }
function coachUI(){
 const special=waiting&&match.down===4&&match.ball<92,active=event?.team??0,off=squads[active].filter(p=>p.side==='offense'),qb=off.find(p=>p.pos==='QB'),call=event?.playCall||selectedPlay,definition=PokeSim.calls[call]||PokeSim.calls.quick;
 const firstRead=call==='inside'||call==='outside'?off.find(p=>p.pos==='HB'):call==='action'?off.find(p=>p.pos==='TE'):off.filter(p=>p.pos==='WR')[call==='deep'?1:0];const target=event?off.find(p=>p.id===event.target)||firstRead:firstRead;
 $('coachQbLabel').textContent=active===0?'YOUR QUARTERBACK':'COMPUTER QUARTERBACK';$('coachQbImage').src=`assets/${qb.id}.png`;$('coachQbImage').alt=qb.name;$('coachQbName').textContent=qb.name;$('coachQbInfo').textContent=(active===0?'KANTO BLUE':'ROCKET RED')+' · QB';$('coachQbOvr').textContent=qb.ovr;
 $('readImage').src=`assets/${target.id}.png`;$('readImage').alt=target.name;$('readName').textContent=target.name;$('readPosition').textContent=target.pos+' · '+(special?'SPECIAL TEAMS':definition.name.toUpperCase());$('readLabel').textContent=definition.kind==='run'?'BALL CARRIER':'FIRST READ';
 $('autoMode').textContent=coaching?'AUTO · OFF':'AUTO · ON';$('autoMode').setAttribute('aria-pressed',String(!coaching));
 $('callPlay').disabled=!running||!waiting||paused||!coaching;
 const label=paused?'PAUSED':!running?'MATCH OVER':waiting?special?'SEND SPECIAL TEAMS':'CALL PLAY':active===1?'CPU DRIVE':'PLAY IN MOTION';$('callPlay').innerHTML=`<span>${waiting&&!paused?'▶':'·'}</span> ${label}`;
 $('playCards').querySelectorAll('[data-call]').forEach(button=>button.disabled=!running||!waiting||paused||!coaching||special);
 $('playbookState').textContent=paused?'Broadcast paused. Resume to continue.':!running?'Full time. Start a new match to call more plays.':waiting?special?'Fourth down. The special teams unit is coming on.':'Choose your play, then send it in.':active===1?'Rocket Red is driving. Your defense plays automatically.':coaching?definition.name+' · your team is executing.':'Auto is calling the plays for both teams.';
 $('playbookNote').textContent=special?(match.ball>=61?'The field goal unit will attempt three points.':'Punt it away and let your defense take the field.'):coaching?'Pick a card to preview the routes. The computer calls its own plays.':'Sit back and watch. Switch Auto off to call your next offensive play.';
 const titles={inside:'Win it in the trenches.',quick:'Get it out quickly.',deep:'Take the top off.',action:'Make them bite.',outside:'Let your speed cook.'};
 $('coachTitle').textContent=special?'Trust your special teams.':active===1?'Defense, hold the line.':titles[call]||'Make your call.';
 $('coachAdvice').textContent=special?'The kick or punt plays out automatically. You’ll get the headset back on the next offensive possession.':active===1?'Rocket Red calls its own plays. Your defenders read, pursue and tackle without any controls.':call==='inside'?`${target.name} attacks the middle behind your line. Strength and lead blocking make the difference.`:call==='outside'?`${target.name} has ${target.ratings.Speed} speed. The outside lane trades reliable yards for a chance to break away.`:call==='quick'?`${qb.name} has ${qb.ratings.Accuracy} accuracy. Get the ball to ${target.name} before the rush arrives.`:call==='deep'?`${target.name} stretches the field. The longer throw needs time in the pocket and carries more risk.`:`Sell the handoff, then find ${target.name} crossing behind the linebackers. The fake takes an extra beat.`;
 $('coachMode').textContent=coaching?'YOU CALL · THEY PLAY':'AUTO BROADCAST · JUST WATCH';
}
function waitForPlay(){event=null;phase=0;waiting=true;replaying=false;replayed=false;particles=[];camera=clamp(match.ball+9,22,78);formation();$('playLabel').textContent='CHOOSE A PLAY';$('toast').textContent='ON THE HEADSET · KANTO BLUE →';$('actionCall').className='action-call';$('status').textContent='YOUR CALL';$('hint').textContent='Pick a play below and call it in. Your team handles the rest.';hud();renderPlayCards();coachUI();}
function advance(){if(match.over)return finish();if(coaching&&match.team===0)return waitForPlay();newPlay();}

function formation(){let t=event?.team??0,off=squads[t].filter(p=>p.side==='offense'),call=PokeSim.calls[selectedPlay],target=call.kind==='run'?off.find(p=>p.pos==='HB'):selectedPlay==='action'?off.find(p=>p.pos==='TE'):off.filter(p=>p.pos==='WR')[selectedPlay==='deep'?1:0];let start=match.ball,depth=call.kind==='run'?9:call.depth[0];previewEvent={team:0,start,end:Math.min(100,start+depth),first:match.first,type:call.kind,playCall:selectedPlay,target:target.id,defender:squads[1].find(p=>p.pos==='ILB').id,gain:depth,complete:call.kind==='pass'};motion=new PokeMotion.PlayMotion(event||previewEvent,[...off,...squads[1-t].filter(p=>p.side==='defense')]);frameState=motion.frame(0);players=frameState.players;}
function newPlay(){waiting=false;event=match.next(coaching&&match.team===0?selectedPlay:null);if(!event)return finish();fieldFX.stop();phase=-.85;replaying=false;replayed=false;particles=[];fxClock=0;formation();$('playLabel').textContent='SET';$('toast').textContent=(event.team===0?'KANTO BLUE':'ROCKET RED')+' · '+(event.type==='run'?'GROUND GAME':event.type==='kick'?'FIELD GOAL':event.type==='punt'?'PUNT':'PASS PLAY');$('actionCall').className='action-call';$('actionCall').textContent='';hud(true);coachUI();}
function start(){enableMusic(true);enableFX();fieldFX.stop();match=new Match(Math.random,{teams:squads});running=true;paused=false;feed=[];elapsed=0;particles=[];camera=29;event=null;waiting=false;$('feed').innerHTML='<li>The teams take the field.</li>';$('banner').style.display='none';$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause simulation');$('start').innerHTML='NEW MATCH <span>↗</span>';$('hint').textContent='The teams take the field.';$('status').textContent='KICKOFF';renderBox();advance()}
function finish(){fieldFX.play('whistle');music.celebrate(true);running=false;waiting=false;coachUI();$('actionCall').className='action-call';$('banner').style.display='flex';let [a,b]=match.score;$('banner').innerHTML=`<span class="eyebrow">FINAL WHISTLE · ${match.plays} PLAYS</span><h2>${a>b?'KANTO WINS!':b>a?'ROCKET WINS!':'TIE GAME'}</h2><p>Kanto Blue ${a} — ${b} Rocket Red<br>Full player stats are below the field.</p><button id="again">WATCH ANOTHER →</button>`;$('again').onclick=start;$('status').textContent='FINAL';$('hint').textContent='The complete box score is ready.';$('toast').textContent='FULL TIME';hud();renderBox();}
function resolve(){let e=event;feed.unshift({text:e.text,q:e.quarter,clock:e.clock,team:e.team,call:e.playCall});$('feed').innerHTML=feed.slice(0,10).map(f=>`<li><small>Q${f.q} · ${Math.floor(f.clock/60)}:${String(f.clock%60).padStart(2,'0')} · ${f.team===0?'BLUE':'RED'}${f.call?' · '+PokeSim.calls[f.call].name.toUpperCase():''}</small>${f.text}</li>`).join('');$('status').textContent=label(e);$('toast').textContent=label(e);$('hint').textContent=e.text;renderBox();hud();if(e.touchdown)music.celebrate()}
function emit(x,y,n,color,kind='dust'){if(!fullEffects)return;for(let i=0;i<n;i++){let angle=Math.random()*Math.PI*2,force=kind==='confetti'?35+Math.random()*100:12+Math.random()*32;particles.push({x,y,vx:Math.cos(angle)*force,vy:Math.sin(angle)*force/9,life:kind==='confetti'?1.8:.35+Math.random()*.3,max:kind==='confetti'?1.8:.65,color,kind,size:kind==='spark'?2:3+Math.random()*3})}if(particles.length>260)particles.splice(0,particles.length-260)}
function update(dt){if(!running||paused||waiting||window.draftIsOpen)return;let step=phase<motion.snap?Math.min(dt,motion.snap-phase):dt*speed*(replaying?.72:1),old=phase;phase=Math.min(phase+step,motion.duration+.08);frameState=motion.frame(Math.max(0,phase));PokeFX.cuesBetween(motion,event,old,phase,replaying).forEach(cue=>fieldFX.play(cue.kind,replaying));players=frameState.players;elapsed+=step;fxClock+=step;
 const crossed=t=>old<t&&phase>=t;
 if(crossed(motion.snap)){emit(320,event.start,8,'#c6d6a0')}
 if((event.complete||event.interception)&&crossed(motion.catchAt)){emit(motion.lane,motion.catchY,14,event.interception?'#fb9a77':'#dbff81','spark')}
 if(crossed(motion.contact)){let c=frameState.carrier;if(event.touchdown){['#d8f474','#eab75a','#72c8e2','#ff9583'].forEach(color=>emit(c.x,c.y,25,color,'confetti'))}else if(frameState.impact){emit(c.x,c.y,22,'#dfcf93');shake=fullEffects?5:0}else if(event.fumble)emit(c.x,c.y,10,'#fba384','spark')}
 if(fullEffects&&fxClock>.065&&frameState.active){fxClock=0;for(const p of players)if(p.move&&((p.carrier)||(p.p.id%4===0)))emit(p.tx,p.ty,1,'#b7c389');if(phase>motion.snap+.2&&phase<motion.runStart+.5)for(const p of players.filter(a=>a.pose==='block'&&a.p.id%3===0))emit(p.tx,p.ty,1,'#ede2a9','spark')}
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=step;p.x+=p.vx*step;p.y+=p.vy*step;p.vx*=Math.exp(-step*3);p.vy+=step*(p.kind==='confetti'?-3:-.5);if(p.life<=0)particles.splice(i,1)}shake*=Math.exp(-step*15);
 let focus=clamp(frameState.focusY+9,22,78);camera+= (focus-camera)*(1-Math.exp(-dt*speed*5));
 $('playLabel').textContent=replaying?'HIGHLIGHT REPLAY':phase<-.3?'READY':phase<motion.snap?'SET':frameState.stage;$('playProgress').style.width=`${frameState.progress*100}%`;
 if(crossed(motion.resolveAt)){if(!replaying)resolve();let e=event,headline=e.touchdown?'TOUCHDOWN!':e.interception?'INTERCEPTED!':e.type==='sack'?'SACK!':e.fumble?'BALL LOOSE!':e.type==='kick'?(e.score?'IT’S GOOD!':'NO GOOD'):e.type==='punt'?'PUNT':e.firstDown?'FIRST DOWN':e.complete||e.type==='run'?`${e.gain>0?'+':''}${e.gain} YARDS`:'INCOMPLETE';$('actionCall').textContent=headline;$('actionCall').className='action-call show '+(e.touchdown?'score':e.interception?'turnover':'');}
 if(phase>=motion.duration){if(fullEffects&&!replayed&&(event.touchdown||event.interception||event.gain>=28)){replaying=true;replayed=true;phase=0;frameState=motion.frame(0);players=frameState.players;particles=[];$('actionCall').className='action-call';$('toast').textContent='↺ HIGHLIGHT REPLAY';return}if(match.over)finish();else advance()}
}
function draw(){stadium.draw({frame:frameState,motion,event:event||previewEvent,phase,elapsed,ambientTime,score:match.score,camera,fullEffects,shake,particles,replaying,paused,waiting:waiting&&!(match.down===4&&match.ball<92),selectedPlay,squads});}
function togglePause(){if(!running)return;paused=!paused;if(paused)fieldFX.stop();else enableFX();$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation');if(!paused&&waiting&&!coaching)advance();coachUI()}
function frame(ts){let dt=Math.min((ts-last)/1000,.06);last=ts;if(!paused&&!window.draftIsOpen)ambientTime+=dt;update(dt);draw();requestAnimationFrame(frame)}
$('callPlay').onclick=()=>{if(running&&waiting&&!paused&&coaching){enableFX();newPlay()}};$('autoMode').onclick=()=>{enableFX();coaching=!coaching;if(running&&waiting&&!paused&&!coaching)advance();coachUI()};
$('start').onclick=()=>{if(!running||confirm('Start a new match and clear this box score?'))start()};$('fieldStart').onclick=start;$('pause').onclick=togglePause;$('sound').onclick=()=>{sound=!sound;fieldFX.setEnabled(sound);saveAudioPref('fx',sound?'on':'off');fxUI();if(sound)fieldFX.prepare().then(()=>fieldFX.play('catch')).catch(error=>console.warn('Field effects could not start:',error))};$('closeDialog').onclick=()=>$('playerDialog').close();$('statTeam').onchange=renderBox;$('scoutTeam').onchange=()=>{scoutingTeam=+$('scoutTeam').value;renderRatings()};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;document.querySelectorAll('[data-speed]').forEach(a=>a.classList.toggle('active',a===b))});document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;document.querySelectorAll('[data-side]').forEach(a=>a.classList.toggle('active',a===b));renderRatings()});document.querySelectorAll('[data-box]').forEach(b=>b.onclick=()=>{box=b.dataset.box;document.querySelectorAll('[data-box]').forEach(a=>a.classList.toggle('active',a===b));renderBox()});window.addEventListener('keydown',e=>{if(e.key==='p'&&!['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName)&&!window.draftIsOpen&&!$('playerDialog').open)togglePause()});
window.startDraftedMatch=(blue,red)=>{squads=[blue,red];preload(squads);const featured=document.querySelector('.team img'),qb=blue.find(p=>p.pos==='QB');featured.src=`assets/${qb.id}.png`;featured.alt=qb.name;event=null;scoutingTeam=0;$('scoutTeam').value='0';renderRatings();const average=ps=>PokeDraft.mean(ps);$('matchupSummary').innerHTML=`<small>THE DRAFTED MATCHUP</small><div><span>KANTO BLUE</span><b>${average(blue)} OVR</b></div><div><span>ROCKET RED</span><b>${average(red)} OVR</b></div>`;start()};
